<script>
 import {executionPrefs} from '../stores/execution-prefs.svelte';
 import {tick} from 'svelte';import {Send,Paperclip} from 'lucide-svelte';import {chat,sendChat,editPrevious,latestRunningRow,stopChat,cancelChatConfirmation} from '../stores/chat.svelte';import {selection} from '../stores/selection.svelte';import {assets} from '../stores/assets.svelte';import {slashCommands} from '../lib/slash.ts';import {keyboard} from '../lib/shortcuts.ts';import {importChatFiles} from '../services/chat-files.js';import Button from '../ui/Button.svelte';
 let {onsend=sendChat}=$props();let input,picker,index=$state(0),hot=$state(false);
 const query=$derived(chat.draft.match(/(?:^|\s)@([^@\n]*)$/)?.[1]??null),slash=$derived(chat.draft.match(/^\/([^\s]*)$/)?.[1]??null);
 const suggestions=$derived.by(()=>{if(query!==null){const available=assets.availableIds;return Object.values(assets.index).filter(a=>available.has(a.id)&&(a.name.toLowerCase().includes(query.toLowerCase())||a.tags?.some(tag=>tag.includes(query)))).slice(0,20);}return slash!==null?slashCommands.filter(command=>command.name.includes(slash)&&(command.name!==slash||command.kind==='fit_ratio')):[];});
 $effect(()=>{chat.draft;index=0;void tick().then(resize);});
 function resize(){if(!input)return;input.style.height='auto';input.style.height=Math.min(input.scrollHeight,176)+'px';}
 async function choose(item){if(query!==null){selection.mention([...selection.mentions,item.id]);chat.draft=chat.draft.replace(/@[^@\n]*$/,'');}else{chat.draft='/'+item.name+(item.kind==='fit_ratio'?' ':'');}index=0;await tick();input.focus();}
 function key(event){if(event.isComposing||event.keyCode===229)return;if(['ArrowDown','ArrowUp'].includes(event.key)&&suggestions.length){event.preventDefault();event.stopPropagation();index=(index+(event.key==='ArrowDown'?1:suggestions.length-1))%suggestions.length;return;}
 if(event.key==='Escape'){if(!suggestions.length&&!latestRunningRow())return;event.preventDefault();event.stopPropagation();if(suggestions.length){chat.draft=query!==null?chat.draft.replace(/@[^@\n]*$/,''):'';return;}const row=latestRunningRow();if(row?.confirmation)cancelChatConfirmation(row);else if(row)void stopChat(row);return;}
 if(event.key==='Backspace'&&!chat.draft&&selection.mentions.length){event.preventDefault();selection.mention(selection.mentions.slice(0,-1));return;}
 if(event.key==='ArrowUp'&&!chat.draft){event.preventDefault();event.stopPropagation();editPrevious();return;}
 if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.stopPropagation();if(suggestions.length)void choose(suggestions[index%suggestions.length]);else void onsend();}}
 async function dropped(event){event.preventDefault();event.stopPropagation();hot=false;try{await importChatFiles([...event.dataTransfer.files].filter(file=>file.type.startsWith('image/')));}catch{}}
</script>
<div class="composer" role="group" aria-label="对话输入" class:hot ondragover={event=>{event.preventDefault();event.stopPropagation();hot=true;}} ondragleave={()=>hot=false} ondrop={dropped}>
 {#if selection.mentions.length}<div class="mention-chips">{#each selection.mentions as id}<button title="移除引用" onclick={()=>selection.mention(selection.mentions.filter(value=>value!==id))}>@{assets.index[id]?.name||id} ×</button>{/each}</div>{/if}
 {#if selection.context?.resolvedTarget.source==='filter'&&selection.context.resolvedTarget.ids.length>executionPrefs.filterCount}<small class="scope-notice" role="status">本次将处理筛选中的 {selection.context.resolvedTarget.ids.length} 张图片，可先缩小范围。</small>{/if}
 <div class="composer-target">{selection.context?.resolvedTarget.source==='mention'?'@引用':selection.selectedIds.length?'已选':selection.context?.resolvedTarget.source==='editor'?'当前图':'筛选结果'} {selection.context?.resolvedTarget.ids.length??selection.selectedIds.length} 张{#if selection.selectedIds.length}<button aria-label="清空已选素材" onclick={()=>selection.clear()}>×</button>{/if}{#if chat.editingId}<span>修改上一条 · 将先撤销其结果</span>{/if}</div>
 {#if suggestions.length}<div class="composer-menu" role="listbox" aria-label={query!==null?'素材引用':'斜杠命令'}>{#each suggestions as item,i}<button role="option" aria-selected={index===i} class:chosen={index===i} onclick={()=>choose(item)}>{query!==null?'@'+item.name:'/'+item.name}</button>{/each}</div>{/if}
 <textarea data-composer bind:this={input} use:keyboard={{keydown:key}} aria-label="处理要求" placeholder="输入要求，@ 引用图片，/ 使用命令" rows="2" bind:value={chat.draft} oninput={resize}></textarea>
 <div class="composer-tools"><input class="ui-sr-only" tabindex="-1" bind:this={picker} type="file" accept="image/png,image/jpeg,image/webp" multiple aria-label="导入对话图片" onchange={async event=>{const files=[...event.currentTarget.files];event.currentTarget.value='';try{await importChatFiles(files);}catch{}}}/><Button variant="subtle" disabled={chat.importing} onclick={()=>picker.click()} title="拖入或添加图片"><Paperclip size={15}/>添加图片</Button><span>{chat.importing?'正在导入…':'Enter 发送 · Shift+Enter 换行'}</span><Button variant="primary" disabled={!chat.draft.trim()||chat.importing} onclick={()=>onsend()}><Send size={14}/>发送</Button></div>
</div>
<style>.composer{position:relative;padding:12px 16px;border-top:1px solid var(--border);background:var(--bg-elev)}.composer.hot{outline:2px solid var(--accent);outline-offset:-2px}.composer-target{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--text-dim);min-height:20px;margin-bottom:8px;flex-wrap:wrap}.composer-target button{border:0;background:transparent;color:var(--text-dim);cursor:pointer}.composer-target span{font-size:11px;color:var(--accent)}.composer textarea{box-sizing:border-box;width:100%;min-height:64px;max-height:176px;resize:none;overflow:auto;line-height:20px;font:13px/20px system-ui,sans-serif;color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:6px;padding:8px}.composer textarea:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.composer-tools{display:flex;align-items:center;gap:8px;margin-top:8px}.composer-tools>span{flex:1;color:var(--text-dim);font-size:10px}.composer-tools :global(.ui-button){font-size:12px;padding:4px 8px}.composer-menu{position:absolute;left:16px;right:16px;bottom:calc(100% - 30px);max-height:260px;overflow:auto;z-index:20;background:var(--bg-elev);border:1px solid var(--border);border-radius:8px;padding:4px;box-shadow:0 6px 16px #0002}.composer-menu button{display:block;width:100%;text-align:left;border:0;background:transparent;color:var(--text);padding:8px;font-size:12px;cursor:pointer}.composer-menu button:hover,.composer-menu button.chosen{background:var(--accent-soft)}.composer-menu button:active{background:var(--bg-sunken)}.composer-menu button:focus-visible,.mention-chips button:focus-visible,.composer-target button:focus-visible{outline:2px solid var(--focus)}.mention-chips{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px}.mention-chips button{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--accent);background:var(--accent-soft);border:1px solid var(--border);border-radius:6px;padding:4px 6px;cursor:pointer}.mention-chips button:hover{border-color:var(--accent)}.mention-chips button:active{background:var(--bg-sunken)}</style>
